def parse_json(json_str):
    def parse_element(s, start):
        # Helper function to parse individual elements in the JSON string
        if s[start] == '{':
            return parse_object(s, start + 1)
        elif s[start] == '[':
            return parse_array(s, start + 1)
        elif s[start] == '"':
            return parse_string(s, start + 1)
        elif s[start] in '0123456789-':
            return parse_number(s, start)
        elif s[start] == 't':
            if s[start:start+4] == 'true':
                return True, start + 4
            else:
                raise ValueError("Invalid JSON syntax")
        elif s[start] == 'f':
            if s[start:start+4] == 'false':
                return False, start + 4
            else:
                raise ValueError("Invalid JSON syntax")
        elif s[start] == 'n':
            if s[start:start+4] == 'null':
                return None, start + 4
            else:
                raise ValueError("Invalid JSON syntax")
        else:
            raise ValueError("Invalid JSON syntax")

    def parse_object(s, start):
        obj = {}
        while s[start] != '}':
            key, end = parse_string(s, start)
            if s[end] != ':':
                raise ValueError("Invalid JSON syntax")
            value, end = parse_element(s, end + 1)
            obj[key] = value
            if s[end] == ',':
                end += 1
            elif s[end] == '}':
                return obj, end
            else:
                raise ValueError("Invalid JSON syntax")
        return obj, end + 1

    def parse_array(s, start):
        array = []
        while s[start] != ']':
            value, end = parse_element(s, start)
            array.append(value)
            if s[end] == ',':
                end += 1
            elif s[end] == ']':
                return array, end
            else:
                raise ValueError("Invalid JSON syntax")
        return array, end + 1

    def parse_string(s, start):
        end = start
        while s[end] != '"':
            if s[end] == '\\':
                end += 2
            else:
                end += 1
        return s[start:end], end + 1

    def parse_number(s, start):
        end = start
        if s[start] in '0123456789':
            while s[end] in '0123456789':
                end += 1
        elif s[start] == '-':
            end += 1
            if s[end] in '0123456789':
                while s[end] in '0123456789':
                    end += 1
            else:
                raise ValueError("Invalid JSON syntax")
        else:
            raise ValueError("Invalid JSON syntax")
        if s[end] in 'eE':
            end += 1
            if s[end] in '0123456789':
                while s[end] in '0123456789':
                    end += 1
            else:
                raise ValueError("Invalid JSON syntax")
            if s[end] in '+-':
                end += 1
                if s[end] in '0123456789':
                    while s[end] in '0123456789':
                        end += 1
                else:
                    raise ValueError("Invalid JSON syntax")
        return float(s[start:end]), end

    try:
        result, _ = parse_element(json_str, 0)
        return result
    except ValueError as e:
        raise e

def parse_json(json_str):
    # Initialize variables to track parsing state
    i = 0
    length = len(json_str)
    result = []
    current_value = ''
    is_string = False
    is_number = False
    is_negative = False

    def parse_string():
        nonlocal i, length, current_value, is_string
        result.append('\"')
        while i < length:
            char = json_str[i]
            if char == '"':
                i += 1
                result.append(char)
                is_string = False
                break
            elif char == '\\':
                i += 1
                if i == length:
                    raise ValueError("Unterminated string constant")
                char = json_str[i]
                if char == 'n':
                    result.append('\n')
                elif char == 'r':
                    result.append('\r')
                elif char == 't':
                    result.append('\t')
                elif char == 'b':
                    result.append('\b')
                elif char == 'f':
                    result.append('\f')
                elif char == 'u':
                    hex_str = json_str[i+1:i+6]
                    i += 6
                    result.append(chr(int(hex_str, 16)))
                else:
                    result.append(char)
            else:
                result.append(char)
                i += 1

    def parse_number():
        nonlocal i, length, current_value, is_number, is_negative
        if json_str[i] == '-':
            is_negative = True
            i += 1
        while i < length and json_str[i].isdigit():
            current_value += json_str[i]
            i += 1
        if i < length and json_str[i] in ('.', 'e', 'E'):
            is_number = True
            current_value += json_str[i]
            i += 1
            if current_value[-1] == 'e' or current_value[-1] == 'E':
                if i < length and json_str[i] in ('+', '-'):
                    i += 1
                if i < length and json_str[i].isdigit():
                    current_value += json_str[i]
                    i += 1
                else:
                    raise ValueError("Invalid number format")
            else:
                while i < length and json_str[i].isdigit():
                    current_value += json_str[i]
                    i += 1
                else:
                    raise ValueError("Invalid number format")
        result.append(int(current_value) if is_negative else float(current_value))

    def parse_value():
        nonlocal i, length, current_value, is_string, is_number, result
        if i == length:
            raise ValueError("Unexpected end of JSON string")
        char = json_str[i]
        if char == '{':
            i += 1
            current_value = {}
            while i < length and json_str[i] != '}':
                key = parse_value()
                if key is None:
                    raise ValueError("Invalid JSON")
                if i < length and json_str[i] == ':':
                    i += 1
                    value = parse_value()
                    if value is None:
                        raise ValueError("Invalid JSON")
                    current_value[key] = value
                elif i < length and json_str[i] == ',':
                    i += 1
                else:
                    raise ValueError("Invalid JSON")
            i += 1
            result.append(current_value)
        elif char == '[':
            i += 1
            current_value = []
            while i < length and json_str[i] != ']':
                value = parse_value()
                if value is None:
                    raise ValueError("Invalid JSON")
                current_value.append(value)
                if i < length and json_str[i] == ',':
                    i += 1
                else:
                    raise ValueError("Invalid JSON")
            i += 1
            result.append(current_value)
        elif char == '"':
            parse_string()
        elif char == 't' and json_str[i:i+3] == 'true':
            i += 3
            result.append(True)
        elif char == 'f' and json_str[i:i+4] == 'false':
            i += 4
            result.append(False)
        elif char == 'n' and json_str[i:i+4] == 'null':
            i += 4
            result.append(None)
        elif char.isdigit():
            parse_number()
        else:
            raise ValueError("Invalid JSON")

    while i < length:
        parse_value()

    return result[0]

def parse_json(json_str):
    def parse_value(s, i):
        # Parse a JSON value at index i
        if s[i] == '{':
            return parse_object(s, i)
        elif s[i] == '[':
            return parse_array(s, i)
        elif s[i] == '"':
            return parse_string(s, i)
        elif s[i].isdigit() or s[i] in '+-':
            return parse_number(s, i)
        elif s[i].lower() in 'truefalse':
            return parse_boolean(s, i)
        elif s[i] == 'n':
            return parse_null(s, i)
        else:
            raise ValueError("Invalid character at index " + str(i))

    def parse_object(s, i):
        # Parse a JSON object at index i
        obj = {}
        i += 1  # Skip '{'
        while s[i] != '}':
            if s[i] != '"':
                raise ValueError("Expected string key")
            key = parse_string(s, i)
            if s[i] != ':':
                raise ValueError("Expected colon after key")
            i += 1  # Skip ':'
            value = parse_value(s, i)
            obj[key] = value
            if s[i] == '}':
                break
            if s[i] != ',':
                raise ValueError("Expected comma or }")
            i += 1  # Skip ','
        i += 1  # Skip '}'
        return obj

    def parse_array(s, i):
        # Parse a JSON array at index i
        arr = []
        i += 1  # Skip '['
        while s[i] != ']':
            value = parse_value(s, i)
            arr.append(value)
            if s[i] == ']':
                break
            if s[i] != ',':
                raise ValueError("Expected comma or ]")
            i += 1  # Skip ','
        i += 1  # Skip ']'
        return arr

    def parse_string(s, i):
        # Parse a JSON string at index i
        i += 1  # Skip '"'
        j = i
        while s[j] != '"':
            if s[j] == '\\':
                j += 1  # Skip escape character
            j += 1
        string = s[i:j]
        i = j + 1  # Skip '"'
        return string

    def parse_number(s, i):
        # Parse a JSON number at index i
        start = i
        if s[i] in '+-':
            i += 1
        while i < len(s) and (s[i].isdigit() or s[i] == '.'):
            i += 1
        number = float(s[start:i])
        return number

    def parse_boolean(s, i):
        # Parse a JSON boolean at index i
        if s[i:i+4] == 'true':
            i += 4
            return True
        elif s[i:i+5] == 'false':
            i += 5
            return False
        else:
            raise ValueError("Expected 'true' or 'false'")

    def parse_null(s, i):
        # Parse a JSON null at index i
        if s[i:i+4] == 'null':
            i += 4
            return None
        else:
            raise ValueError("Expected 'null'")

    return parse_value(json_str, 0)

def parse_json(json_str):
    def parse_value(token):
        if token[0] == '{':
            return parse_dict(token[1:-1])
        elif token[0] == '[':
            return parse_list(token[1:-1])
        elif token[0].isdigit() or token[0] in '-.':
            return float(token) if '.' in token else int(token)
        elif token == 'true':
            return True
        elif token == 'false':
            return False
        elif token == 'null':
            return None
        else:
            return str(token)

    def parse_dict(body):
        if not body:
            return {}
        key, value = parse_pair(body)
        rest = parse_dict(body[key+2:])  # Skip the comma and space
        return {key: value} | rest

    def parse_pair(body):
        if body[0] == '"':
            index = body.find('"', 1)  # Find the next quote
            key = body[1:index]  # Extract the key
            index += 1  # Skip the next quote
            value = parse_value(body[index:])  # Parse the value
            return key, value

    def parse_list(body):
        if not body:
            return []
        element, rest = parse_element(body)
        return [element] + parse_list(rest[2:])  # Skip the comma and space

    def parse_element(body):
        index = body.find(',')
        if index == -1:
            return parse_value(body), ''
        else:
            element = parse_value(body)
            rest = body[index+1:]
            return element, rest

    # Start parsing from the first non-whitespace character
    tokens = iter(json_str.lstrip())
    token = next(tokens)
    if token != '{':
        raise ValueError("Invalid JSON")
    return parse_dict(token[1:-1])
